// Generated by crew — do not edit; it is rewritten every time the agent starts.
//
// This extension joins a pi session to the crew daemon:
// - the crew tools: crew's MCP server, registered with the session and
//   declared to the model like built-in tools (pi 1.0); on a pi without
//   MCP, each tool is registered as a pi tool that runs `crew ctl tool`;
// - team messages, pushed into the session over the daemon's Unix socket
//   (`crew bridge` holds it open and prints one JSON line per delivery);
// - the session's life, reported to the daemon (`crew hook …`): when it is
//   up, each turn, each tool call, the model and how full the context is;
// - compactions the daemon asks for, run between turns.
//
// Plain Node: no imports from pi itself, so it loads under any pi.
import { execFile, spawn } from "node:child_process"

const CREW_BIN: string = __CREW_BIN__
const IDENTITY: string = __IDENTITY__

type Delivery = { ids: string[]; text: string }
type CompactOrder = { instructions?: string }
type ToolSpec = { name: string; description: string; inputSchema: unknown }
type Run = { code: number; stdout: string; stderr: string }

const env = { ...process.env, CREW_IDENTITY: IDENTITY }

// A compaction the daemon asked for, waiting for the running turn to end.
let compactWhenIdle: CompactOrder | undefined
let compacting = false
let turnRunning = false
// What the session was last reported to run on.
let lastModel = ""
// crew starts every session with a prompt of its own (its task, a handoff,
// "you were restarted"), which pi takes once its MCP servers are up. Team
// messages that arrive before that turn starts wait for it: delivered
// first, they would run ahead of it — without the crew tools, and the
// prompt they overtook would be lost.
const FIRST_TURN_WAIT_MS = 30_000
let firstTurn = false
const held: string[] = []

function run(args: string[]): Promise<Run> {
  return new Promise(resolve => {
    execFile(CREW_BIN, args, { env, maxBuffer: 16 * 1024 * 1024 }, (error, stdout, stderr) => {
      const failed = error as (Error & { code?: unknown }) | null
      const code = failed === null ? 0 : typeof failed.code === "number" ? failed.code : 1
      resolve({ code, stdout: String(stdout ?? ""), stderr: String(stderr ?? "") })
    })
  })
}

function report(event: string, payload: object): void {
  void run(["hook", event, "--identity", IDENTITY, JSON.stringify(payload)])
}

function parse(line: string): Delivery | undefined {
  try {
    const value = JSON.parse(line)
    if (typeof value.text === "string" && Array.isArray(value.ids)) return value
  } catch {
    // not a delivery line
  }
  return undefined
}

function parseCompact(line: string): CompactOrder | undefined {
  try {
    const value = JSON.parse(line)
    if (value !== null && typeof value.compact === "object" && value.compact !== null) {
      const instructions = value.compact.instructions
      return typeof instructions === "string" && instructions !== "" ? { instructions } : {}
    }
  } catch {
    // not a compaction order
  }
  return undefined
}

function modelOf(ctx: any): { model?: string; effort?: string } {
  const model = ctx?.model
  const name = model === undefined ? undefined : model.provider ? `${model.provider}/${model.id}` : String(model.id)
  return { model: name, effort: undefined }
}

// What the session runs on, when it differs from the last report.
function reportModel(pi: any, ctx: any, event: string, extra: object = {}): void {
  const { model } = modelOf(ctx)
  let effort: string | undefined
  try {
    const level = pi.getThinkingLevel?.()
    if (typeof level === "string" && level !== "" && level !== "off") effort = level
  } catch {
    // no thinking level to speak of
  }
  const step = `${model ?? ""}\n${effort ?? ""}`
  if (step !== lastModel || event === "session-start") {
    lastModel = step
    report(event, { ...extra, model, effort })
  }
}

function reportUsage(ctx: any): void {
  try {
    const usage = ctx.getContextUsage?.()
    if (usage && typeof usage.tokens === "number" && typeof usage.contextWindow === "number") {
      report("usage", { context: { tokens: usage.tokens, window: usage.contextWindow } })
    }
  } catch {
    // nothing known yet
  }
}

// Compact the conversation between turns, as the daemon asked. One pi
// refuses (nothing to compact yet, the model unreachable) is reported, so
// the daemon stops asking; a failure to even ask is not, and it asks again.
function compact(ctx: any, order: CompactOrder): void {
  if (compacting) return
  compacting = true
  try {
    ctx.compact({
      ...(order.instructions === undefined ? {} : { customInstructions: order.instructions }),
      onComplete: () => {
        compacting = false
        report("compacted", {})
      },
      onError: (error: unknown) => {
        compacting = false
        report("compact-skipped", { reason: error instanceof Error ? error.message : String(error) })
      },
    })
  } catch {
    compacting = false
  }
}

async function deliver(pi: any, ctx: any, line: string): Promise<void> {
  const order = parseCompact(line)
  if (order !== undefined) {
    if (turnRunning) compactWhenIdle = order
    else compact(ctx, order)
    return
  }
  const delivery = parse(line)
  if (delivery === undefined) return
  // Idle: a turn of its own; mid-turn: queued until the turn ends.
  pi.sendUserMessage(delivery.text, { deliverAs: "followUp" })
  if (delivery.ids.length > 0) {
    await run(["delivered", "--identity", IDENTITY, ...delivery.ids])
  }
}

// Deliver what waited for the first turn (queued behind it, as follow-ups).
function release(pi: any, ctx: any): void {
  if (firstTurn) return
  firstTurn = true
  for (const line of held.splice(0)) void deliver(pi, ctx, line)
}

function pump(pi: any, ctx: any): void {
  // Should pi never start the first turn, messages are not held forever.
  setTimeout(() => release(pi, ctx), FIRST_TURN_WAIT_MS).unref?.()
  const bridge = spawn(CREW_BIN, ["bridge", "--identity", IDENTITY], { env, stdio: ["ignore", "pipe", "ignore"] })
  let buffer = ""
  bridge.stdout.setEncoding("utf8")
  bridge.stdout.on("data", (chunk: string) => {
    buffer += chunk
    let newline = buffer.indexOf("\n")
    while (newline >= 0) {
      const line = buffer.slice(0, newline)
      buffer = buffer.slice(newline + 1)
      newline = buffer.indexOf("\n")
      if (line.trim() === "") continue
      if (firstTurn) void deliver(pi, ctx, line)
      else held.push(line)
    }
  })
  bridge.on("error", () => {
    // Without the bridge the daemon falls back to the terminal.
  })
  process.on("exit", () => {
    try {
      bridge.kill()
    } catch {
      // already gone
    }
  })
}

async function registerTools(pi: any): Promise<void> {
  if (typeof pi.registerMcpServer === "function") {
    pi.registerMcpServer("crew", {
      command: CREW_BIN,
      args: ["mcp", "--identity", IDENTITY],
      exposure: "direct",
      description: "Your crew team: messages, tasks, reviews and git, as the briefing describes",
    })
    return
  }
  const listed = await run(["ctl", "tools"])
  if (listed.code !== 0) return
  let specs: ToolSpec[]
  try {
    specs = JSON.parse(listed.stdout)
  } catch {
    return
  }
  for (const spec of specs) {
    if (typeof spec.name !== "string") continue
    pi.registerTool({
      name: spec.name,
      label: spec.name,
      description: spec.description,
      parameters: spec.inputSchema,
      async execute(_toolCallId: string, params: unknown) {
        const result = await run(["ctl", "tool", spec.name, JSON.stringify(params ?? {})])
        const text = result.code === 0 ? result.stdout.trimEnd() : `Error: ${(result.stderr || result.stdout).trim()}`
        return { content: [{ type: "text", text: text === "" ? "ok" : text }], details: {} }
      },
    })
  }
}

export default async function (pi: any): Promise<void> {
  await registerTools(pi)
  let pumping = false

  pi.on("session_start", (_event: unknown, ctx: any) => {
    const manager = ctx.sessionManager
    report("session-start", {
      session_id: manager?.getSessionId?.(),
      transcript_path: manager?.getSessionFile?.(),
      ...modelOf(ctx),
    })
    lastModel = ""
    if (!pumping) {
      pumping = true
      pump(pi, ctx)
    }
  })

  pi.on("agent_start", (_event: unknown, ctx: any) => {
    turnRunning = true
    reportModel(pi, ctx, "model")
    report("turn-start", {})
    release(pi, ctx)
  })

  pi.on("model_select", (_event: unknown, ctx: any) => {
    reportModel(pi, ctx, "model")
  })

  pi.on("tool_execution_start", (event: any) => {
    report("tool-start", { tool_name: event.toolName, tool_input: event.args })
  })

  pi.on("agent_end", (event: any, ctx: any) => {
    turnRunning = false
    const messages: any[] = Array.isArray(event?.messages) ? event.messages : []
    const last = [...messages].reverse().find(m => m?.role === "assistant")
    const payload: Record<string, unknown> = {}
    if (last?.stopReason === "error") {
      payload.error = "error"
      payload.error_details = String(last.errorMessage ?? "")
    }
    report("turn-end", payload)
    reportUsage(ctx)
    if (compactWhenIdle !== undefined) {
      const order = compactWhenIdle
      compactWhenIdle = undefined
      compact(ctx, order)
    }
  })

  pi.on("session_compact", () => {
    report("compacted", {})
  })

  pi.on("session_shutdown", () => {
    report("exiting", {})
  })
}
